import gurobipy as gp
from gurobipy import GRB
capacity = None
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('capacity.csv'):
        capacity = int(rec['values']['Capacity'])
        break
if capacity is None:
    raise ValueError('Missing capacity in LEGACY_RECORDS')
products = []
profit = {}
weight = {}
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('products.csv'):
        pname = rec['values']['ProductName']
        products.append(pname)
        try:
            profit[pname] = int(rec['values']['Value'])
            weight[pname] = int(rec['values']['Weight'])
        except Exception as e:
            raise ValueError(f'Missing or invalid Value/Weight for {pname}: {e}')
if len(products) != 25:
    raise ValueError(f'Expected 25 products, got {len(products)}')
if set(profit) != set(products) or set(weight) != set(products):
    raise ValueError('Profit/weight keys do not match products')
m = gp.Model('CarSales2')
x_vars = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((profit[p] * x_vars[p] for p in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[p] * x_vars[p] for p in products)) <= capacity, name='capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')